L["Apply / Cancel"] = "应用 / 取消"
-- en: "Apply pending changes before leaving? Use Cancel on the page to discard them."
L["Apply pending changes before leaving? Use Cancel on the page to discard them."] = "离开前要应用待处理的更改吗？使用页面上的“取消”可放弃这些更改。"
