L["Expand code editor"] = "展开代码编辑器"
-- en: "Restore code editor"
L["Restore code editor"] = "还原代码编辑器"
-- en: "Choose a source helper and the local name used to call it in this Lua body. Renaming the local name does not rewrite code. Source modules distinguish helpers with the same name."
L["Choose a source helper and the local name used to call it in this Lua body. Renaming the local name does not rewrite code. Source modules distinguish helpers with the same name."] = "选择一个源辅助函数，以及在此 Lua 函数体中调用它时使用的本地名称。重命名本地名称不会重写代码。源模块用于区分同名的辅助函数。"
