L["the cooldown on {item} {comparison} {duration}{carrying}"] = "{item}的冷却{comparison}{duration}{carrying}"
-- en: "Questie"
L["Questie"] = "Questie"
-- en: "Enable Questie integration"
L["Enable Questie integration"] = "启用 Questie 集成"
-- en: "Waiting for Questie."
