L["One rounded numeric result from the original formula."] = "来自原始公式的一个舍入后的数字结果。"
-- en: "Optional collection of key values selecting entries; its own keys are ignored."
L["Optional collection of key values selecting entries; its own keys are ignored."] = "可选的键值集合，用于选择条目；其自身的键会被忽略。"
